<script setup lang="ts">
import { reactive,watch,computed,nextTick,onMounted,onUnmounted } from 'vue';
import { X,FolderOpen,ArrowUp,ChevronRight,ChevronDown,RefreshCw,TriangleAlert,Server,Play,Square,HardDrive } from '@lucide/vue';
import { desk,safely,request,operation,apiPath,refresh,loadProject,applyPreset,removeSelected,makeDirectory,restoreConfirm,browse,openBrowse,serverImport,service,notify,resetProjectNavigation } from './store';
import { bytes,presets,type Data } from './model';
import FileIcon from './FileIcon.vue';
const form=reactive<Data>({});
const repairVersions=computed(()=>desk.releaseFiles.find(file=>file.path===form.path)?.versions||[]);
const title=computed(()=>({ 'project-create':'创建项目',directory:'新建文件夹','preset-confirm':'修改维护方式',remove:'移出所选内容',group:'可选内容','group-members':'加入可选内容',restore:'恢复设置与文件',correct:'修复玩家副本',rollback:'创建回滚发布','problem-confirm':'处理历史坏版本',browse:'选择服务器路径','import-server':'从服务器导入',service:'下载服务'} as Record<string,string>)[desk.dialog]||'操作');
watch(()=>desk.dialog,()=>{for(const k of Object.keys(form))delete form[k];if(desk.dialog==='project-create')Object.assign(form,{id:`modpack-${(desk.state.projects?.length||0)+1}`,displayName:'',sourceDirectory:'',publicBaseUrl:''});if(desk.dialog==='group')Object.assign(form,{id:'',title:'',description:'',defaultInstall:true});Object.assign(form,desk.dialogData);if(desk.dialog==='remove')form.action='DELETE';});
async function submit(){if(['problem-confirm','correct'].includes(desk.dialog)&&!String(form.reason||'').trim())throw new Error('请填写处理原因，玩家会看到这条说明');if(desk.dialog==='group'&&(desk.project?.maintenance?.optionalGroups||[]).some((g:Data)=>String(g.title).trim()===String(form.title||'').trim()&&g.id!==form.id))throw new Error('已有同名的可选内容，请换一个名称');await operation(async()=>{
 switch(desk.dialog){
 case 'project-create':{if(desk.uploading||desk.tasks.some(t=>t.state!=='done'))throw new Error('请先完成或移出导入清单，再创建项目');const project=await request('/api/projects','POST',form);desk.projectId=project.id;resetProjectNavigation();await refresh();desk.view='files';desk.settingsDirty=false;break;}
 case 'group':await request(apiPath('/maintenance/group'),'POST',form);await loadProject();notify('可选内容已保存');break;
 case 'group-members':await request(apiPath('/maintenance/group-members'),'POST',{groupId:form.groupId,items:desk.selection.map(e=>({path:e.path,directory:e.directory,modId:e.componentId})),add:true});await loadProject();notify('已加入可选内容，检查并发布后生效');break;
 case 'rollback':await request(apiPath('/rollback'),'POST',{targetReleaseId:form.release.releaseId,displayVersion:form.version,changelog:form.notes,acknowledgePlayerUpgrade:form.ack});await refresh();notify('回滚版本已发布');break;
 case 'problem-confirm':await request(apiPath('/maintenance/withdraw'),'POST',{reason:form.reason,versions:form.versions});await loadProject();notify('问题处理已保存，检查并发布后生效');break;
 case 'correct':await request(apiPath('/maintenance/correct'),'POST',{path:form.path,mode:form.mode,reason:form.reason,badSha256:form.badSha256});await loadProject();notify('修复要求已保存，检查并发布后生效');break;
 }
 desk.dialog='';
 },'正在保存…');}
async function browseConfirm(){const path=desk.browseSelected||desk.browse.path||desk.browsePath;if(desk.browseAction==='import'){const entry=desk.browse.entries?.find((e:Data)=>e.path===path);if(!entry?.regularFile)throw new Error('请选择一个文件');await serverImport(path);}else if(desk.dialogData.returnDialog){const action=desk.browseAction;desk.dialogData={...desk.dialogData,[action]:path};desk.dialog=desk.dialogData.returnDialog;}else{desk.browseValues[desk.browseAction]=path;desk.dialog='';}}
function close(){if(!desk.busy)desk.dialog='';}
let priorFocus:HTMLElement|null=null;
watch(()=>desk.dialog,(value,previous)=>{if(value&&!previous)priorFocus=document.activeElement as HTMLElement;void nextTick(()=>{if(value)document.querySelector<HTMLElement>('.native-dialog input:not([type=radio],[type=checkbox]),.native-dialog select,.native-dialog .sheet-body button,.native-dialog footer button')?.focus();else priorFocus?.focus();});});
function trap(event:KeyboardEvent){if(!desk.dialog)return;if(event.key==='Escape'){event.preventDefault();close();}if(event.key==='Tab'){const nodes=[...document.querySelectorAll<HTMLElement>('.native-dialog button:not(:disabled),.native-dialog input:not(:disabled),.native-dialog select:not(:disabled),.native-dialog textarea:not(:disabled),.native-dialog summary')].filter(e=>e.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}
onMounted(()=>window.addEventListener('keydown',trap));onUnmounted(()=>window.removeEventListener('keydown',trap));
</script>
<template>
 <transition name="sheet"><div v-if="desk.dialog" class="modal-backdrop" @click.self="close"><section class="native-dialog" :class="{wide:desk.dialog==='browse'||desk.dialog==='restore'}" role="dialog" aria-modal="true" :aria-label="title"><header><h2>{{title}}</h2><button class="icon-button filled" aria-label="关闭弹窗" :disabled="desk.busy" @click="close"><X :size="16"/></button></header>
  <form v-if="desk.dialog==='project-create'" class="sheet-body" @submit.prevent="safely(submit)"><p>每个项目独立管理自己的文件、发布记录和玩家端配置。</p><label>项目名称<input v-model="form.displayName" placeholder="例如 我的整合包" required></label><label>项目 ID<input v-model="form.id" pattern="[A-Za-z0-9][A-Za-z0-9._-]*" required><small>用于更新地址，创建后保持不变。</small></label><label>整合包目录<div class="field-with-button"><input v-model="form.sourceDirectory" placeholder="存放 mods、config 的目录" required><button type="button" aria-label="浏览目录" @click="desk.dialogData={...form,returnDialog:'project-create'};openBrowse('directory','sourceDirectory',form.sourceDirectory)"><FolderOpen :size="16"/></button></div></label><label>玩家更新地址<input v-model="form.publicBaseUrl" type="url" placeholder="https://updates.example.com/" required></label><footer><button type="button" @click="close">取消</button><button class="accent" :disabled="desk.busy">创建项目</button></footer></form>
  <form v-else-if="desk.dialog==='directory'" class="sheet-body" @submit.prevent="safely(()=>makeDirectory(form.path))"><label>目录路径<input v-model="form.path" required><small>可以输入多级路径，例如 config/my-mod。</small></label><footer><button type="button" @click="close">取消</button><button class="accent">创建文件夹</button></footer></form>
  <div v-else-if="desk.dialog==='preset-confirm'" class="sheet-body"><p>所选 {{desk.selection.length}} 项内容将使用下方维护方式。文件夹内的文件会一起应用。</p><div class="option-list" role="radiogroup" aria-label="维护方式"><label v-for="key in ['SYNC','REQUIRED','INITIAL']" :key="key" class="option-card" :class="{active:form.preset===key}"><input v-model="form.preset" type="radio" :value="key"><span><strong>{{presets[key].label}}</strong><small>{{presets[key].description}}</small></span></label></div><div class="inset-list"><div v-for="entry in desk.selection" :key="entry.path" class="inset-row"><FileIcon :name="entry.path" :directory="entry.directory" :size="22"/><span>{{entry.path}}</span></div></div><footer><button @click="close">取消</button><button class="accent" :disabled="desk.busy" @click="safely(async()=>{await applyPreset(form.preset);desk.dialog='';})">确认修改</button></footer></div>
  <div v-else-if="desk.dialog==='remove'" class="sheet-body"><p>所选 {{desk.selection.length}} 项内容会先归档，再移出整合包目录。发布后，按下方方式处理玩家副本。</p><div class="option-list" role="radiogroup" aria-label="玩家副本处理方式"><label class="option-card" :class="{active:form.action==='DELETE'}"><input v-model="form.action" type="radio" value="DELETE"><span><strong>移除玩家副本</strong><small>之后装回的匹配副本也会先备份，再移出。</small></span></label><label class="option-card" :class="{active:form.action==='RELEASE'}"><input v-model="form.action" type="radio" value="RELEASE"><span><strong>停止维护，留给玩家</strong><small>玩家已有内容留在原处，之后由玩家管理。</small></span></label></div><footer><button @click="close">取消</button><button class="danger-button" :disabled="desk.busy" @click="safely(()=>removeSelected(form.action))">确认移出 {{desk.selection.length}} 项</button></footer></div>
  <form v-else-if="desk.dialog==='group'" class="sheet-body" @submit.prevent="safely(submit)"><p>玩家可以整组安装或停用这组内容。</p><label>内容名称<input v-model="form.title" placeholder="例如 光影与美化" required></label><label>说明<textarea v-model="form.description" rows="3" placeholder="告诉玩家，这组内容适合什么情况"></textarea></label><label class="check toggle-line"><span>默认安装<small>玩家没有主动选择时，是否安装这组内容</small></span><input v-model="form.defaultInstall" type="checkbox" class="switch"></label><details v-if="form.id" class="disclosure-inline"><summary>内容 ID</summary><input :value="form.id" readonly aria-label="内容 ID"></details><footer><button type="button" @click="close">取消</button><button class="accent">保存可选内容</button></footer></form>
  <form v-else-if="desk.dialog==='group-members'" class="sheet-body" @submit.prevent="safely(submit)"><p>将所选 {{desk.selection.length}} 项加入一组可选内容。</p><div v-if="desk.project?.maintenance?.optionalGroups?.length" class="option-list" role="radiogroup" aria-label="可选内容"><label v-for="group in desk.project.maintenance.optionalGroups" :key="group.id" class="option-card" :class="{active:form.groupId===group.id}"><input v-model="form.groupId" type="radio" :value="group.id" required><span><strong>{{group.title}}</strong><small>{{group.defaultInstall?'默认安装':'默认不安装'}}{{group.description?` · ${group.description}`:''}}</small></span></label></div><p v-else class="inset-note">还没有可选内容，先新建一组。</p><button type="button" class="text-action" @click="desk.dialog='group';desk.dialogData={}">新建可选内容</button><footer><button type="button" @click="close">取消</button><button class="accent" :disabled="!form.groupId">确认加入</button></footer></form>
  <div v-else-if="desk.dialog==='restore'" class="sheet-body"><p>确认以下变化后，再执行恢复。之后需要检查并发布，玩家才会收到。</p><div class="restore-changes"><article v-for="(change,i) in desk.operationPlan?.changes||[]" :key="i"><strong>{{change.path||change.setting||change.label||change.field||'设置变化'}}</strong><div><pre>{{change.before??change.current??'—'}}</pre><ChevronRight :size="16"/><pre class="after">{{change.after??change.restored??'—'}}</pre></div></article><p v-if="!desk.operationPlan?.changes?.length" class="inset-note">当前设置已与发布版本一致。</p></div><footer><button @click="close">取消</button><button class="accent" :disabled="desk.busy||!desk.operationPlan?.changes?.length" @click="safely(restoreConfirm)">确认恢复</button></footer></div>
  <form v-else-if="desk.dialog==='rollback'" class="sheet-body" @submit.prevent="safely(submit)"><p>使用 {{form.release?.displayVersion}} 的内容，创建一个新的发布版本。已经公开的历史记录保持不变。</p><label>新版本号<input v-model="form.version" required placeholder="例如 1.0.2"></label><label>回滚说明<textarea v-model="form.notes" rows="3" placeholder="告诉玩家为什么回到这个版本"></textarea></label><label class="check"><input v-model="form.ack" type="checkbox">玩家使用 0.2.0 或更新的玩家端</label><footer><button type="button" @click="close">取消</button><button class="accent">创建回滚发布</button></footer></form>
  <div v-else-if="desk.dialog==='problem-confirm'" class="sheet-body"><div class="notice-card warning"><TriangleAlert :size="20"/><p>选择的 {{form.versions?.length}} 个历史坏版本，将在发布后要求玩家移出。即使之前已停止维护，也会处理匹配的副本。</p></div><label>问题说明<input v-model="form.reason" placeholder="例如 会导致客户端崩溃"><small>玩家会看到这条说明。</small></label><footer><button @click="close">取消</button><button class="danger-button" @click="safely(submit)">保存问题处理</button></footer></div>
  <div v-else-if="desk.dialog==='import-server'" class="sheet-body"><p>选择管理端所在电脑或服务器上的文件，先检查后导入。</p><button class="choice-button" @click="openBrowse('file','import')"><span class="choice-icon"><HardDrive :size="20"/></span><span><strong>浏览服务器文件</strong><small>文件会先进入私有暂存区，确认后才写入整合包目录</small></span><ChevronRight :size="16"/></button></div>
  <form v-else-if="desk.dialog==='correct'" class="sheet-body" @submit.prevent="safely(submit)"><p>用标准目录中的 <strong>{{form.path}}</strong> 修复玩家副本。玩家原文件会先备份。</p><label>修复范围<div class="select-capsule wide"><select v-model="form.mode"><option value="ONCE">每个玩家修复一次</option><option value="KNOWN_BAD">只修复选中的历史坏版本</option></select><ChevronDown :size="13"/></div></label><div v-if="form.mode==='KNOWN_BAD'" class="inset-list"><label v-for="version in repairVersions" :key="version.sha256" class="history-version"><input v-model="form.badSha256" type="checkbox" :value="version.sha256"><span>{{version.version||version.sha256.slice(0,10)}}</span><small>{{version.firstRelease}} · {{bytes(version.size)}}</small></label><p v-if="!repairVersions.length" class="inset-note">这个文件还没有历史版本。</p></div><label>修复说明<input v-model="form.reason" required placeholder="例如 修复导致崩溃的配置"></label><footer><button type="button" @click="close">取消</button><button class="accent" :disabled="desk.busy||(form.mode==='KNOWN_BAD'&&!form.badSha256?.length)">保存修复要求</button></footer></form>
  <div v-else-if="desk.dialog==='browse'" class="sheet-body server-browser"><div class="browse-toolbar"><button class="icon-button filled" aria-label="上一级服务器目录" :disabled="!desk.browse.parentPath&&!desk.browse.parent" @click="safely(()=>browse(desk.browse.parentPath||desk.browse.parent))"><ArrowUp :size="16"/></button><input v-model="desk.browsePath" aria-label="服务器路径" @keyup.enter="safely(()=>browse(desk.browsePath))"><button @click="safely(()=>browse(desk.browsePath))">转到</button></div><div v-if="desk.browse.roots?.length" class="chip-row"><button v-for="root in desk.browse.roots||[]" :key="root.path||root" class="chip" @click="safely(()=>browse(root.path||root))">{{root.label||root.path||root}}</button></div><div class="browse-entries"><button v-for="entry in desk.browse.entries||[]" :key="entry.path" :class="{selected:desk.browseSelected===entry.path}" @click="desk.browseSelected=entry.path" @dblclick="entry.directory?safely(()=>browse(entry.path)):desk.browseSelected=entry.path"><FileIcon :name="entry.name" :directory="entry.directory" :size="26"/><span>{{entry.name}}</span><small>{{entry.directory?'文件夹':bytes(entry.size)}}</small><ChevronRight v-if="entry.directory" :size="14"/></button><p v-if="!desk.browse.entries?.length" class="inset-note">这个目录是空的</p></div><footer><span class="footer-path" :title="desk.browseSelected||desk.browsePath">{{desk.browseSelected||desk.browsePath}}</span><button @click="close">取消</button><button class="accent" @click="safely(browseConfirm)">{{desk.browseAction==='import'?'暂存所选文件':'使用这个目录'}}</button></footer></div>
  <div v-else-if="desk.dialog==='service'" class="sheet-body"><div class="service-card" :class="{on:desk.state.publicService?.running}"><span class="service-icon"><Server :size="22"/></span><div><strong>{{desk.state.publicService?.running?'下载服务运行中':'下载服务已停止'}}</strong><p>{{desk.state.publicService?.address||`${desk.state.settings?.httpHost}:${desk.state.settings?.httpPort}`}}</p><small v-if="desk.state.publicService?.detail">{{desk.state.publicService.detail}}</small></div><i class="service-dot"/></div><p>玩家端从下载服务获取发布内容。本机关闭窗口后，服务会继续在托盘中运行。</p><footer><button @click="safely(()=>service('stop'))"><Square :size="13"/>停止</button><button @click="safely(()=>service('restart'))"><RefreshCw :size="14"/>重启</button><button class="accent" @click="safely(()=>service('start'))"><Play :size="14"/>启动下载服务</button></footer></div>
 </section></div></transition>
</template>
